schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    citta TEXT,
    email TEXT UNIQUE
);

CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    categoria TEXT NOT NULL,
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);

CREATE TABLE vendite (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    data_ordine DATE NOT NULL,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    importo_totale NUMERIC(12,2) NOT NULL CHECK (importo_totale >= 0),
    PRIMARY KEY (id, data_ordine)
) PARTITION BY RANGE (data_ordine);

CREATE TABLE vendite_2023 PARTITION OF vendite
    FOR VALUES FROM ('2023-01-01') TO ('2024-01-01');

CREATE TABLE vendite_2024 PARTITION OF vendite
    FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
CREATE TABLE vendite_default PARTITION OF vendite DEFAULT;
